{"command":"mkdir -p /tmp/probe && cat > /tmp/probe/Probe.java <<'EOF'
import org.apache.commons.text.StringSubstitutor;

public class Probe {
    public static void main(String[] a) {
        System.out.println("commons-text on cp: " + StringSubstitutor.class.getProtectionDomain()
                .getCodeSource().getLocation());
        StringSubstitutor s = StringSubstitutor.createInterpolator();
        String[] tokens = {
            "${base64Decoder:aGk=}",
            "${base64Encoder:aGk=}",
            "${env:PATH}",
            "${sys:user.name}",
            "${date:yyyy}",
            "${java:version}",
            "${const:java.lang.Integer.MAX_VALUE}",
            "${url:UTF-8:http://127.0.0.1:18080/probe-url-lookup}",
            "${dns:localhost|address}",
            "${script:javascript:'pwned'.toUpperCase()}",
            "${localhost:canonical-name}",
            "${file:UTF-8:/etc/hostname}",
            "${properties:/etc/hostname::k}",
            "${resourceBundle:x::y}",
            "${urlDecoder:a%20b}",
        };
        for (String t : tokens) {
            String out;
            try { out = s.replace(t); } catch (Throwable e) { out = "<ERR " + e + ">"; }
            boolean changed = !out.equals(t);
            String shown = out.length() > 90 ? out.substring(0, 90) + "..." : out;
            System.out.printf("%-8s %-55s -> %s%n", changed ? "ACTIVE" : "off", t, changed ? shown : t);
        }
    }
}
EOF
cd /tmp/probe && javac -cp /root/.m2/repository/org/apache/commons/commons-text/1.9/commons-text-1.9.jar Probe.java 2>&1 | tail -3 && echo COMPILED"}

